const fs = require('fs');
let c = fs.readFileSync('src/store/user.ts', 'utf8');

// Remove secure-storage import
const impRe = /import \{[^}]+\} from ["']@\/services\/secure-storage["'];/;
c = c.replace(impRe, '');

// Add auth key helpers after APIAny line
c = c.replace('const APIAny = API as any;', 'const APIAny = API as any;\n\nconst AUTH_KEY_PREFIX = "auth:";\nfunction authKey(key) { return AUTH_KEY_PREFIX + key; }');

// Replace hydrateAuthFromStorage
const hydrateRe = /async function hydrateAuthFromStorage\(\)[\s\S]*?^\}/m;
c = c.replace(hydrateRe, `function hydrateAuthFromStorage() {
    if (!token.value) {
      token.value = localStorage.getItem(authKey("token"));
    }
    if (!user.value) {
      const raw = localStorage.getItem(authKey("user"));
      if (raw) { try { user.value = JSON.parse(raw); } catch(e) {} }
    }
  }`);

// Replace persistAuth
const persistRe = /async function persistAuth\(\)[\s\S]*?^\}/m;
c = c.replace(persistRe, `function persistAuth() {
    if (token.value) {
      localStorage.setItem(authKey("token"), token.value);
    } else {
      localStorage.removeItem(authKey("token"));
    }
    if (user.value) {
      localStorage.setItem(authKey("user"), JSON.stringify(user.value));
    } else {
      localStorage.removeItem(authKey("user"));
    }
  }`);

// Remove all 'await ' calls to persistAuth and hydrateAuthFromStorage
c = c.replace(/await hydrateAuthFromStorage\(\)/g, 'hydrateAuthFromStorage()');
c = c.replace(/await persistAuth\(\)/g, 'persistAuth()');

// Update comment about Bridge
c = c.replace('Bridge 安全存储', 'localStorage');

fs.writeFileSync('src/store/user.ts', c);
console.log('Done, length:', c.length);
"@

